INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('state-machine','intermediate','What is state minimization?',ARRAY['Merging equivalent states','Adding more states','Removing inputs','Reducing outputs'],0,'Equivalent states produce same outputs and transitions.',15),
('state-machine','intermediate','What are equivalent states?',ARRAY['States with same outputs and next states for all inputs','States with same name','States with same encoding','Adjacent states'],0,'Two states are equivalent if they behave identically.',15),
('state-machine','intermediate','What is the state minimization algorithm?',ARRAY['Partition refinement','Binary search','Bubble sort','Dijkstra''s'],0,'Partition refinement merges equivalent states.',15),
('state-machine','intermediate','What is a partition in state minimization?',ARRAY['Group of states that may be equivalent','Group of inputs','Group of outputs','Group of transitions'],0,'Partitions are iteratively refined to find equivalents.',15),
('state-machine','intermediate','What is state assignment?',ARRAY['Assigning binary codes to states','Assigning inputs','Assigning outputs','Assigning transitions'],0,'State assignment affects circuit complexity.',15),
('state-machine','intermediate','What are common state assignment strategies?',ARRAY['Binary, Gray, one-hot, random','Sequential, parallel','Ascending, descending','Odd, even'],0,'Different encodings optimize different metrics.',15),
('state-machine','intermediate','What is a Mealy-to-Moore conversion?',ARRAY['Adding states to move outputs from arcs to nodes','Removing states','Adding inputs','Removing outputs'],0,'Mealy→Moore: split states so output depends only on state.',15),
('state-machine','intermediate','What is a Moore-to-Mealy conversion?',ARRAY['Moving outputs from states to transitions','Adding states','Removing transitions','Adding inputs'],0,'Moore→Mealy: move output to incoming transition arc.',15),
('state-machine','intermediate','What is a sequence detector?',ARRAY['FSM that recognizes a specific input pattern','FSM that counts','FSM that adds','FSM that divides'],0,'Sequence detectors find specific bit patterns.',15),
('state-machine','intermediate','How many states for a Mealy sequence detector for ''101''?',ARRAY['4','3','5','2'],0,'Mealy ''101'' detector: S0, S1, S2, S3 (found).',15),
('state-machine','intermediate','How many states for a Moore sequence detector for ''101''?',ARRAY['5','4','3','2'],0,'Moore needs one extra state for output delay.',15),
('state-machine','intermediate','What is a Mealy sequence detector advantage?',ARRAY['Fewer states than Moore','More states','Faster clock','Less logic'],0,'Mealy uses fewer states but output can glitch.',15),
('state-machine','intermediate','What is a glitch in Mealy machines?',ARRAY['Brief incorrect output during state transition','Permanent error','Clock error','Reset error'],0,'Mealy output can change mid-transition (asynchronous).',15),
('state-machine','intermediate','How to avoid Mealy glitches?',ARRAY['Register the output or use Moore machine','Add more states','Increase clock','Remove inputs'],0,'Registered Mealy or Moore avoids glitches.',15),
('state-machine','intermediate','What is a traffic light controller?',ARRAY['FSM controlling light sequences','Analog circuit','Combinational logic','Counter only'],0,'Traffic lights cycle: green→yellow→red→green.',15),
('state-machine','intermediate','How many states does a simple traffic light controller have?',ARRAY['4 (G, Y, R in two directions)','2','3','6'],0,'Two directions: NS-green, NS-yellow, EW-green, EW-yellow.',15),
('state-machine','intermediate','What is a vending machine controller?',ARRAY['FSM accepting coins and dispensing products','Counter','Adder','Comparator'],0,'Vending machines track credit and product selection.',15),
('state-machine','intermediate','What is an elevator controller?',ARRAY['FSM managing floor and door states','Counter','Timer','Comparator'],0,'Elevator: states for idle, moving, door open/closed.',15),
('state-machine','intermediate','What is a deadlock state?',ARRAY['State with no exit transitions','Initial state','Final state','Error state'],0,'Deadlock: machine stuck, cannot progress.',15),
('state-machine','intermediate','What is a livelock in an FSM?',ARRAY['Machine cycles without making progress','Machine is stuck','Machine resets','Machine stops'],0,'Livelock: active but no useful work done.',15),
('state-machine','intermediate','What is a reachability analysis?',ARRAY['Finding all states reachable from initial','Counting states','Minimizing states','Encoding states'],0,'Reachability: BFS/DFS from initial state.',15),
('state-machine','intermediate','What is an unreachable state?',ARRAY['State never entered from initial state','State with no inputs','State with no outputs','Final state'],0,'Unreachable states can be removed.',15),
('state-machine','intermediate','What is a state transition table?',ARRAY['Maps (state, input) → (next state, output)','Maps inputs to outputs','Maps states to codes','Maps clocks to transitions'],0,'Transition table fully specifies FSM behavior.',15),
('state-machine','intermediate','What is the next-state equation?',ARRAY['Boolean function for each flip-flop input','Clock equation','Output equation','Reset equation'],0,'Next-state eq: D_i = f(current state, inputs).',15),
('state-machine','intermediate','What is the output equation?',ARRAY['Boolean function for FSM outputs','Next-state function','Clock function','Reset function'],0,'Output eq: Y = f(state) [Moore] or f(state, input) [Mealy].',15),
('state-machine','intermediate','What is a D flip-flop input equation?',ARRAY['D = next-state function','D = current state','D = clock','D = output'],0,'For D-FF: D input = desired next state.',15),
('state-machine','intermediate','What is a JK flip-flop input equation?',ARRAY['J and K derived from next-state table','D = next state','T = toggle','S = set'],0,'JK: J=1 set, K=1 reset, J=K=1 toggle, J=K=0 hold.',15),
('state-machine','intermediate','What is a T flip-flop input equation?',ARRAY['T = 1 when state should change','T = 0 always','T = clock','T = output'],0,'T-FF: T=1 toggles, T=0 holds.',15),
('state-machine','intermediate','What is excitation table?',ARRAY['Table showing FF inputs needed for each transition','Truth table','State table','K-map'],0,'Excitation tables give required inputs for state changes.',15),
('state-machine','intermediate','What is the D-FF excitation table?',ARRAY['D = next state (always)','D = 0','D = 1','D = current state'],0,'D-FF: D = Q(next), regardless of current.',15),
('state-machine','intermediate','What is the JK-FF excitation for Q→Q''?',ARRAY['J=1, K=1','J=0, K=0','J=1, K=0','J=0, K=1'],0,'Toggle: J=K=1.',15),
('state-machine','intermediate','What is the JK-FF excitation for Q→Q (hold)?',ARRAY['J=0, K=0','J=1, K=1','J=1, K=0','J=0, K=1'],0,'Hold: J=K=0.',15),
('state-machine','intermediate','What is the T-FF excitation for Q→Q''?',ARRAY['T=1','T=0','T=Q','T=Q'''],0,'Toggle: T=1.',15),
('state-machine','intermediate','What is the T-FF excitation for Q→Q (hold)?',ARRAY['T=0','T=1','T=Q','T=Q'''],0,'Hold: T=0.',15),
('state-machine','intermediate','What is a K-map for state machine design?',ARRAY['Minimizes next-state and output equations','Counts states','Encodes states','Tests states'],0,'K-maps simplify Boolean expressions for FF inputs.',15),
('state-machine','intermediate','What is a binary counter with parallel load?',ARRAY['Counter that can be preset to any value','Counter that only counts up','Counter that only counts down','Ripple counter'],0,'Parallel load: load arbitrary value, then count.',15),
('state-machine','intermediate','What is a self-starting counter?',ARRAY['Eventually reaches valid counting sequence from any state','Starts at 0','Starts at max','Never starts'],0,'Self-starting: all unused states lead to valid states.',15),
('state-machine','intermediate','What is a non-self-starting counter?',ARRAY['May get stuck in unused states','Always starts correctly','Counts backwards','Never counts'],0,'Non-self-starting: unused states may form deadlock cycles.',15),
('state-machine','intermediate','How do you make a counter self-starting?',ARRAY['Map unused states to valid states','Add more flip-flops','Remove flip-flops','Increase clock speed'],0,'Design next-state logic to redirect unused states.',15),
('state-machine','intermediate','What is a Gray code counter?',ARRAY['Counter using Gray code encoding','Binary counter','One-hot counter','BCD counter'],0,'Gray code: one bit changes per transition, no glitches.',15),
('state-machine','intermediate','What is the advantage of Gray code in state machines?',ARRAY['Only one bit changes per transition','Fewer states','Less power','Higher speed'],0,'Single bit change avoids decoding glitches.',15),
('state-machine','intermediate','What is a clock divider?',ARRAY['Circuit that divides clock frequency','Amplifies clock','Generates clock','Buffers clock'],0,'Clock divider: toggle FF divides by 2.',15),
('state-machine','intermediate','What division ratio does a single toggle FF give?',ARRAY['Divide by 2','Divide by 4','Divide by 8','Divide by 10'],0,'One T-FF with T=1 divides clock by 2.',15),
('state-machine','intermediate','How many FFs for divide-by-16?',ARRAY['4','2','3','8'],0,'2^4 = 16, so 4 toggle FFs.',15),
('state-machine','intermediate','What is a digital clock manager (DCM)?',ARRAY['PLL/DLL for clock synthesis and phase shifting','Counter','Divider','Buffer'],0,'DCM: phase shifting, frequency synthesis, deskew.',15),
('state-machine','intermediate','What is clock domain crossing?',ARRAY['Transferring data between different clock domains','Clock division','Clock buffering','Clock generation'],0,'CDC requires synchronizers to prevent metastability.',15),
('state-machine','intermediate','What is a two-flop synchronizer?',ARRAY['Two flip-flops in series for CDC','Two flip-flops in parallel','Two flip-flops with feedback','Single flip-flop'],0,'Two-stage synchronizer reduces metastability probability.',15),
('state-machine','intermediate','What is the MTBF of a synchronizer?',ARRAY['Mean Time Between Failures from metastability','Maximum Time Before Failure','Minimum Time Between Fixes','Mean Toggle Bit Frequency'],0,'MTBF depends on clock frequency, data rate, and FF parameters.',15),
('state-machine','intermediate','What is asynchronous reset?',ARRAY['Reset independent of clock','Reset synchronized with clock','No reset','Clock-dependent reset'],0,'Async reset: immediate effect, but may cause metastability.',15),
('state-machine','intermediate','What is synchronous reset?',ARRAY['Reset only takes effect on clock edge','Reset is immediate','No reset needed','Reset is asynchronous'],0,'Sync reset: safer, avoids reset deassertion metastability.',15);